def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n >= 99:
        return 'D'

    opp = [h[1] for h in history]
    me = [h[0] for h in history]

    total_opp_d = opp.count('D')

    if n >= 12:
        recent12 = opp[-12:]
        if recent12.count('D') >= 8:
            return 'D'

    if total_opp_d * 5 > n * 3:
        return 'D'

    last_opp = opp[-1]
    last_me = me[-1]

    if last_opp == 'D':
        if n >= 12 and last_me == 'D' and me[-2] == 'D' and opp[-2] == 'D':
            recent10 = opp[-10:]
            if recent10.count('C') >= 8:
                return 'C'
        return 'D'

    return 'C'
